use zwen_core::paper::{Source,Metadata,ReadingOptions};
fn text_options()->ReadingOptions{ReadingOptions{read_images:false,..Default::default()}}
fn source()->Source{Source{meta:Metadata{id:"0123456789abcdef0123456789abcdef".into(),name:"long.pdf".into(),page_count:3,readable_pages:3},pages:vec!["INTRO Evidence ".repeat(30000),"METHOD supports mechanism".into(),"EXPERIMENT lower error".into()]}}
#[test]fn long_documents_offer_a_small_index_and_range_bound_tools(){let s=source();let p=s.prepare(&text_options(),"分析").unwrap();assert!(p.prompt.len()<20*1024);assert!(!p.prompt.contains("INTRO Evidence INTRO Evidence"));let mut d=p.document.unwrap();assert!(!d.has_read());let bad=d.execute("read_paper_page",r#"{"page":4}"#,32768);assert!(bad.content.contains("不在"));assert!(!d.has_read());let read=d.execute("read_paper_page",r#"{"page":2}"#,32768);assert!(read.content.contains("METHOD supports"));assert!(d.coverage().contains("完整返回文字的页：2"));let hit=d.execute("search_paper",r#"{"query":"experiment"}"#,32768);assert!(hit.content.contains("EXPERIMENT"));assert!(d.coverage().contains("未通过读页工具读取的页：1、3"));assert!(d.execute("shell",r#"{"command":"id"}"#,32768).content.contains("只允许"));}
#[test]fn unicode_offsets_and_delivery_budgets_do_not_claim_undelivered_material(){let mut s=source();s.pages[1]="甲乙🙂丙丁".into();let mut d=s.prepare(&text_options(),"分析").unwrap().document.unwrap();assert!(d.execute("read_paper_page",r#"{"page":2,"offset":1,"limit":2}"#,1).content.contains("预算不足"));assert!(!d.has_read());assert!(d.execute("read_paper_page",r#"{"page":2,"offset":1,"limit":2}"#,32768).content.contains("乙🙂"));assert!(d.coverage().contains("部分返回文字的页：2"));d.execute("read_paper_page",r#"{"page":2,"offset":0,"limit":5}"#,32768);assert!(d.coverage().contains("完整返回文字的页：2"));}
#[test]fn small_ranges_keep_single_request_and_large_sources_can_bind(){let s=source();let p=s.prepare(&ReadingOptions{start_page:2,..text_options()},"分析").unwrap();assert!(p.document.is_none());assert!(p.prompt.contains("EXPERIMENT"));assert!(s.prepare(&ReadingOptions{read_images:true,..Default::default()},"分析").is_ok());}
#[test]fn tools_cannot_read_or_search_outside_saved_pages(){let mut s=source();s.pages[0]="OUTSIDE_ONLY_MARKER".into();s.pages[1]="INSIDE evidence ".repeat(25000);let mut d=s.prepare(&ReadingOptions{start_page:2,..text_options()},"分析").unwrap().document.unwrap();assert!(d.execute("read_paper_page",r#"{"page":1}"#,32768).content.contains("不在"));assert!(d.execute("search_paper",r#"{"query":"OUTSIDE_ONLY_MARKER"}"#,32768).content.contains("没有字面命中"));assert!(!d.has_read());}
#[test]fn source_binding_persists_long_document_options_for_followups(){let root=std::env::temp_dir().join(format!("zwen-long-bind-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));std::fs::create_dir(&root).unwrap();{let mut lib=zwen_core::paper::Library::open(&root).unwrap();let s=source();lib.add(&s.meta.id,&s.meta.name,b"%PDF-1.4 synthetic",s.pages.clone()).unwrap();lib.bind("paper-long-test",&s.meta.id,&text_options()).unwrap();let (source,options)=lib.session("paper-long-test").unwrap().unwrap();assert!(source.prepare(&options,"追问方法").unwrap().document.is_some());}std::fs::remove_dir_all(root).unwrap();}
